public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {
    }

    public static Map<String, Decimal> getRates(
        String baseCurrency,
        Set<String> quoteCurrencies
    ) {
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException(
                'At least one quote currency is required.'
            );
        }

        String normalizedBase = normalizeCurrencyCode(baseCurrency);

        Set<String> normalizedQuotes = new Set<String>();
        for (String quoteCurrency : quoteCurrencies) {
            normalizedQuotes.add(normalizeCurrencyCode(quoteCurrency));
        }

        if (normalizedQuotes.isEmpty()) {
            throw new ExchangeRateException(
                'At least one quote currency is required.'
            );
        }

        List<String> sortedQuotes = new List<String>(normalizedQuotes);
        sortedQuotes.sort();

        String endpoint =
            'callout:FB_Exchange_Rates/v1/latest' +
            '?base=' + EncodingUtil.urlEncode(normalizedBase, 'UTF-8') +
            '&symbols=' + String.join(sortedQuotes, ',');

        HttpResponse response;
        for (Integer attempt = 0; attempt < 2; attempt++) {
            HttpRequest request = new HttpRequest();
            request.setEndpoint(endpoint);
            request.setMethod('GET');
            request.setHeader('Accept', 'application/json');

            response = new Http().send(request);

            if (response.getStatusCode() != 503) {
                break;
            }
        }

        if (response.getStatusCode() != 200) {
            throw new ExchangeRateException(
                'Exchange rate request failed with status code ' +
                response.getStatusCode() +
                '.'
            );
        }

        return parseRates(response.getBody(), normalizedQuotes);
    }

    private static String normalizeCurrencyCode(String currencyCode) {
        if (currencyCode == null) {
            throw new ExchangeRateException('Currency code is required.');
        }

        String normalized = currencyCode.trim().toUpperCase();

        if (!Pattern.matches('[A-Z]{3}', normalized)) {
            throw new ExchangeRateException(
                'Invalid currency code: ' + currencyCode
            );
        }

        return normalized;
    }

    private static Map<String, Decimal> parseRates(
        String body,
        Set<String> requestedCurrencies
    ) {
        if (String.isBlank(body)) {
            throw new ExchangeRateException(
                'Exchange rate response body could not be parsed.'
            );
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new ExchangeRateException(
                'Exchange rate response body could not be parsed: ' +
                e.getMessage()
            );
        }

        try {
            if (!(parsed instanceof Map<String, Object>)) {
                throw new ExchangeRateException(
                    'Exchange rate response body could not be parsed.'
                );
            }

            Map<String, Object> responseMap = (Map<String, Object>) parsed;
            Object ratesObject = responseMap.get('rates');

            if (!(ratesObject instanceof Map<String, Object>)) {
                throw new ExchangeRateException(
                    'Exchange rate response body could not be parsed.'
                );
            }

            Map<String, Object> ratesMap = (Map<String, Object>) ratesObject;
            Map<String, Decimal> result = new Map<String, Decimal>();

            for (String currencyCode : requestedCurrencies) {
                if (
                    !ratesMap.containsKey(currencyCode) ||
                    ratesMap.get(currencyCode) == null
                ) {
                    throw new ExchangeRateException(
                        'Missing exchange rate for currency: ' + currencyCode
                    );
                }

                Object rawRate = ratesMap.get(currencyCode);
                Decimal rate;

                if (rawRate instanceof Decimal) {
                    rate = (Decimal) rawRate;
                } else if (rawRate instanceof Integer) {
                    rate = Decimal.valueOf((Integer) rawRate);
                } else if (rawRate instanceof Long) {
                    rate = Decimal.valueOf((Long) rawRate);
                } else if (rawRate instanceof Double) {
                    rate = Decimal.valueOf((Double) rawRate);
                } else if (rawRate instanceof String) {
                    rate = Decimal.valueOf((String) rawRate);
                } else {
                    throw new ExchangeRateException(
                        'Invalid exchange rate for currency: ' + currencyCode
                    );
                }

                result.put(currencyCode, rate);
            }

            return result;
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException(
                'Exchange rate response body could not be parsed: ' +
                e.getMessage()
            );
        }
    }
}
