public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            // Validate maxRows
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }

            // Validate fields list
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('fields must not be null or empty.');
            }

            // Validate and resolve object (case-insensitive)
            if (String.isBlank(objectApiName)) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }
            String trimmedObjectName = objectApiName.trim();
            Schema.SObjectType objectType = null;
            Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
            for (String key : globalDescribe.keySet()) {
                if (key != null && key.equalsIgnoreCase(trimmedObjectName)) {
                    objectType = globalDescribe.get(key);
                    break;
                }
            }
            if (objectType == null) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }

            Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();

            if (!objectDescribe.isAccessible()) {
                throw new SearchException(
                    'User cannot read object: ' + objectDescribe.getName()
                );
            }
            if (!objectDescribe.isQueryable()) {
                throw new SearchException(
                    'Object is not queryable: ' + objectDescribe.getName()
                );
            }

            // Build case-insensitive field map using canonical field names
            Map<String, Schema.DescribeFieldResult> fieldsByLowerName =
                new Map<String, Schema.DescribeFieldResult>();
            for (Schema.SObjectField fieldToken : objectDescribe.fields.getMap().values()) {
                Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
                fieldsByLowerName.put(fieldDescribe.getName().toLowerCase(), fieldDescribe);
            }

            // Validate SELECT fields
            List<String> selectFieldNames = new List<String>();
            Set<String> seenSelectFields = new Set<String>();
            // Id is always selected first
            seenSelectFields.add('id');
            for (String rawFieldName : fields) {
                Schema.DescribeFieldResult fieldDescribe =
                    resolveField(fieldsByLowerName, rawFieldName);
                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException(
                        'User cannot read field: ' + fieldDescribe.getName()
                    );
                }
                String lowerName = fieldDescribe.getName().toLowerCase();
                if (!seenSelectFields.contains(lowerName)) {
                    seenSelectFields.add(lowerName);
                    selectFieldNames.add(fieldDescribe.getName());
                }
            }

            // Validate filters
            Map<String, Object> bindVariables = new Map<String, Object>();
            List<String> conditions = new List<String>();
            if (filters != null && !filters.isEmpty()) {
                Integer bindIndex = 0;
                for (String rawFilterField : filters.keySet()) {
                    Schema.DescribeFieldResult fieldDescribe =
                        resolveField(fieldsByLowerName, rawFilterField);
                    if (!fieldDescribe.isAccessible()) {
                        throw new SearchException(
                            'User cannot read field: ' + fieldDescribe.getName()
                        );
                    }
                    if (!fieldDescribe.isFilterable()) {
                        throw new SearchException(
                            'Field cannot be filtered: ' + fieldDescribe.getName()
                        );
                    }
                    String bindName = 'bind' + String.valueOf(bindIndex);
                    bindIndex++;
                    // Only canonical, validated field names are concatenated.
                    // Values are passed exclusively as bind variables.
                    conditions.add(fieldDescribe.getName() + ' = :' + bindName);
                    bindVariables.put(bindName, filters.get(rawFilterField));
                }
            }

            // Validate ORDER BY field
            String canonicalOrderByField = null;
            if (String.isNotBlank(orderByField)) {
                Schema.DescribeFieldResult fieldDescribe =
                    resolveField(fieldsByLowerName, orderByField);
                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException(
                        'User cannot read field: ' + fieldDescribe.getName()
                    );
                }
                if (!fieldDescribe.isSortable()) {
                    throw new SearchException(
                        'Field cannot be sorted: ' + fieldDescribe.getName()
                    );
                }
                canonicalOrderByField = fieldDescribe.getName();
            }

            // Build query using only canonical object/field names from describe
            String query = 'SELECT Id';
            for (String selectField : selectFieldNames) {
                query += ', ' + selectField;
            }
            query += ' FROM ' + objectDescribe.getName();

            if (!conditions.isEmpty()) {
                query += ' WHERE ' + String.join(conditions, ' AND ');
            }

            if (canonicalOrderByField != null) {
                query += ' ORDER BY ' + canonicalOrderByField + ' ASC';
            }

            // maxRows has been validated as an Integer in 1..200, so it is safe as a literal
            query += ' LIMIT ' + String.valueOf(maxRows);

            // USER_MODE enforces object/field-level security; 'with sharing'
            // on the class enforces record sharing. Bind variables prevent
            // SOQL injection from filter values.
            return Database.queryWithBinds(
                query,
                bindVariables,
                AccessLevel.USER_MODE
            );
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException(e.getMessage());
        }
    }

    private static Schema.DescribeFieldResult resolveField(
        Map<String, Schema.DescribeFieldResult> fieldsByLowerName,
        String rawFieldName
    ) {
        if (String.isBlank(rawFieldName)) {
            throw new SearchException('Field does not exist: ' + rawFieldName);
        }
        Schema.DescribeFieldResult fieldDescribe =
            fieldsByLowerName.get(rawFieldName.trim().toLowerCase());
        if (fieldDescribe == null) {
            throw new SearchException('Field does not exist: ' + rawFieldName);
        }
        return fieldDescribe;
    }
}
