public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(
            required=true
            label='Email'
            description='Email address to look up'
        )
        public String email;
    }

    public class Result {
        @InvocableVariable(
            label='Contact Id'
            description='Id of the matching Contact, if found'
        )
        public Id contactId;

        @InvocableVariable(
            label='Found'
            description='True if a matching Contact was found'
        )
        public Boolean found;
    }

    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds an existing Contact by email address. If multiple Contacts match, the earliest created Contact is returned.'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        List<String> normalizedEmails = new List<String>(requests.size());
        Set<String> emailsToQuery = new Set<String>();

        for (Request request : requests) {
            String normalizedEmail = normalizeEmail(
                request == null ? null : request.email
            );
            normalizedEmails.add(normalizedEmail);

            if (normalizedEmail != null) {
                emailsToQuery.add(normalizedEmail);
            }
        }

        Map<String, Id> contactIdByEmail = new Map<String, Id>();

        if (!emailsToQuery.isEmpty()) {
            // Single bulk query. SOQL string matching is case-insensitive,
            // and results are ordered so the first Contact seen for each
            // normalized email is the earliest created one.
            for (Contact contactRecord : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :emailsToQuery
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String contactEmail = normalizeEmail(contactRecord.Email);

                if (contactEmail != null && !contactIdByEmail.containsKey(contactEmail)) {
                    contactIdByEmail.put(contactEmail, contactRecord.Id);
                }
            }
        }

        for (Integer i = 0; i < requests.size(); i++) {
            String normalizedEmail = normalizedEmails[i];
            Id matchedContactId = normalizedEmail == null
                ? null
                : contactIdByEmail.get(normalizedEmail);

            Result result = new Result();
            result.contactId = matchedContactId;
            result.found = matchedContactId != null;
            results.add(result);
        }

        return results;
    }

    private static String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }
}
