public class OrderPayloadParser {

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Order payload body is null or blank.');
        }

        try {
            Object parsed;
            try {
                parsed = JSON.deserializeUntyped(body);
            } catch (Exception e) {
                throw new PayloadException('Order payload is not valid JSON: ' + e.getMessage());
            }

            if (parsed == null || !(parsed instanceof Map<String, Object>)) {
                throw new PayloadException('Order payload must be a JSON object.');
            }

            Map<String, Object> root = (Map<String, Object>) parsed;

            Order result = new Order();
            result.lines = new List<Line>();
            result.total = 0;

            // orderNumber (required, from "number")
            Object numberValue = root.get('number');
            if (!(numberValue instanceof String) || String.isBlank((String) numberValue)) {
                throw new PayloadException('Order payload is missing a valid "number".');
            }
            result.orderNumber = (String) numberValue;

            // orderDate (optional, from "date")
            Object dateValue = root.get('date');
            if (dateValue == null) {
                result.orderDate = null;
            } else if (dateValue instanceof String) {
                String dateText = ((String) dateValue).trim();
                if (String.isBlank(dateText)) {
                    result.orderDate = null;
                } else {
                    try {
                        result.orderDate = Date.valueOf(dateText);
                    } catch (Exception e) {
                        throw new PayloadException('Order payload has an invalid "date": ' + dateText);
                    }
                }
            } else {
                throw new PayloadException('Order payload "date" must be a string.');
            }

            // currencyCode (optional, from "currency")
            result.currencyCode = asOptionalString(root.get('currency'), 'currency');

            // customerEmail (optional, from "customer.email")
            result.customerEmail = null;
            Object customerValue = root.get('customer');
            if (customerValue != null) {
                if (!(customerValue instanceof Map<String, Object>)) {
                    throw new PayloadException('Order payload "customer" must be an object.');
                }
                Map<String, Object> customer = (Map<String, Object>) customerValue;
                result.customerEmail = asOptionalString(customer.get('email'), 'customer.email');
            }

            // lines (optional)
            Object linesValue = root.get('lines');
            Decimal total = 0;

            if (linesValue != null) {
                if (!(linesValue instanceof List<Object>)) {
                    throw new PayloadException('Order payload "lines" must be an array.');
                }

                List<Object> rawLines = (List<Object>) linesValue;
                for (Object rawLine : rawLines) {
                    if (rawLine == null || !(rawLine instanceof Map<String, Object>)) {
                        throw new PayloadException('Each order line must be an object.');
                    }
                    Map<String, Object> lineMap = (Map<String, Object>) rawLine;

                    Line line = new Line();

                    // sku (required)
                    Object skuValue = lineMap.get('sku');
                    if (!(skuValue instanceof String) || String.isBlank((String) skuValue)) {
                        throw new PayloadException('Order line is missing a valid "sku".');
                    }
                    line.sku = (String) skuValue;

                    // quantity (required, positive integer)
                    Object quantityValue = lineMap.get('quantity');
                    if (quantityValue == null) {
                        throw new PayloadException('Order line is missing "quantity".');
                    }
                    line.quantity = toQuantity(quantityValue);
                    if (line.quantity == null || line.quantity <= 0) {
                        throw new PayloadException('Order line "quantity" must be positive.');
                    }

                    // unitPrice (required, non-negative)
                    Object unitPriceValue = lineMap.get('unitPrice');
                    if (unitPriceValue == null) {
                        throw new PayloadException('Order line is missing "unitPrice".');
                    }
                    line.unitPrice = toDecimal(unitPriceValue, 'unitPrice');
                    if (line.unitPrice < 0) {
                        throw new PayloadException('Order line "unitPrice" must not be negative.');
                    }

                    // discount (optional, default 0, fraction 0..1)
                    Object discountValue = lineMap.get('discount');
                    if (discountValue == null) {
                        line.discount = 0;
                    } else {
                        line.discount = toDecimal(discountValue, 'discount');
                        if (line.discount < 0 || line.discount > 1) {
                            throw new PayloadException('Order line "discount" must be between 0 and 1.');
                        }
                    }

                    Decimal rawTotal = Decimal.valueOf(line.quantity) * line.unitPrice * (1 - line.discount);
                    line.lineTotal = rawTotal.setScale(2, RoundingMode.HALF_UP);
                    total += line.lineTotal;

                    result.lines.add(line);
                }
            }

            result.total = total.setScale(2, RoundingMode.HALF_UP);
            return result;
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Invalid order payload: ' + e.getMessage());
        }
    }

    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order is required.');
        }
        try {
            Integer lineCount = (order.lines == null) ? 0 : order.lines.size();
            Decimal total = (order.total == null) ? 0 : order.total;

            JSONGenerator generator = JSON.createGenerator(false);
            generator.writeStartObject();
            if (order.orderNumber == null) {
                generator.writeNullField('number');
            } else {
                generator.writeStringField('number', order.orderNumber);
            }
            generator.writeStringField('status', 'RECEIVED');
            generator.writeNumberField('lineCount', lineCount);
            generator.writeNumberField('total', total);
            generator.writeEndObject();
            String result = generator.getAsString();
            generator.close();
            return result;
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Could not build acknowledgement: ' + e.getMessage());
        }
    }

    private static String asOptionalString(Object value, String fieldName) {
        if (value == null) {
            return null;
        }
        if (value instanceof String) {
            return (String) value;
        }
        throw new PayloadException('Order payload "' + fieldName + '" must be a string.');
    }

    private static Decimal toDecimal(Object value, String fieldName) {
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        if (value instanceof Double) {
            return Decimal.valueOf(String.valueOf(value));
        }
        throw new PayloadException('Order line "' + fieldName + '" must be a number.');
    }

    private static Integer toQuantity(Object value) {
        Decimal decimalValue = toDecimal(value, 'quantity');
        Decimal integralValue = decimalValue.setScale(0, RoundingMode.DOWN);
        if (decimalValue != integralValue) {
            throw new PayloadException('Order line "quantity" must be an integer.');
        }
        if (integralValue < -2147483648 || integralValue > 2147483647) {
            throw new PayloadException('Order line "quantity" is out of range.');
        }
        return integralValue.intValue();
    }
