@IsTest
private class OpportunityWonHandlerTest {
    private static final String WON = 'Closed Won';
    private static final String HANDOVER = 'Handover to Customer Success';

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static Account createAccount(String accountName, String rating) {
        Account acc = new Account(Name = accountName, Rating = rating);
        insert acc;
        return acc;
    }

    private static Account getAccount(Id accountId) {
        return [
            SELECT Id, Name, Rating
            FROM Account
            WHERE Id = :accountId
            LIMIT 1
        ];
    }

    private static Opportunity makeOpportunity(
        String oppName,
        Id accountId,
        String stageName,
        Date closeDate,
        String nextStep
    ) {
        return new Opportunity(
            Name = oppName,
            AccountId = accountId,
            StageName = stageName,
            CloseDate = closeDate,
            NextStep = nextStep
        );
    }

    private static Opportunity getOpportunity(Id oppId) {
        return [
            SELECT Id, Name, StageName, NextStep, AccountId, OwnerId, CloseDate
            FROM Opportunity
            WHERE Id = :oppId
            LIMIT 1
        ];
    }

    private static List<Task> getTasks(Id oppId) {
        return [
            SELECT Id, Subject, WhatId, OwnerId, ActivityDate, Priority
            FROM Task
            WHERE WhatId = :oppId
            ORDER BY CreatedDate ASC
        ];
    }

    private static List<Task> getTasks(Set<Id> oppIds) {
        return [
            SELECT Id, Subject, WhatId, OwnerId, ActivityDate, Priority
            FROM Task
            WHERE WhatId IN :oppIds
            ORDER BY CreatedDate ASC
        ];
    }

    private static Task getSingleTask(Id oppId) {
        List<Task> tasks = getTasks(oppId);
        Assert.areEqual(
            1,
            tasks.size(),
            'Expected exactly one Task for Opportunity ' + oppId
        );
        return tasks[0];
    }

    private static void assertKickoffTask(
        Task task,
        Id oppId,
        Id expectedOwnerId,
        Date expectedActivityDate
    ) {
        Assert.areEqual('Customer kick-off', task.Subject, 'Task Subject is wrong.');
        Assert.areEqual(oppId, task.WhatId, 'Task WhatId must be the Opportunity.');
        Assert.areEqual(
            expectedOwnerId,
            task.OwnerId,
            'Task OwnerId must be the Opportunity owner.'
        );
        Assert.areEqual(
            expectedActivityDate,
            task.ActivityDate,
            'Task ActivityDate must be CloseDate + 7 days.'
        );
        Assert.areEqual('High', task.Priority, 'Task Priority must be High.');
    }

