    @IsTest
    private static void mixedUpdate_onlyNewlyWonOpportunitiesAreHandedOver() {
        Account alreadyWonAcc = createAccount('Mixed Update Already Won Acc', 'Cold');
        Account toWinAcc = createAccount('Mixed Update To Win Acc', 'Cold');
        Account stayingAcc = createAccount('Mixed Update Staying Acc', 'Cold');
        Account leavingAcc = createAccount('Mixed Update Leaving Acc', 'Cold');

        Opportunity alreadyWon = makeOpportunity(
            'Mixed already won',
            alreadyWonAcc.Id,
            WON,
            Date.newInstance(2026, 7, 1),
            'Already original'
        );
        Opportunity toWin = makeOpportunity(
            'Mixed to win',
            toWinAcc.Id,
            'Prospecting',
            Date.newInstance(2026, 7, 2),
            'To win original'
        );
        Opportunity staying = makeOpportunity(
            'Mixed staying open',
            stayingAcc.Id,
            'Prospecting',
            Date.newInstance(2026, 7, 3),
            'Staying original'
        );
        Opportunity leaving = makeOpportunity(
            'Mixed leaving won',
            leavingAcc.Id,
            WON,
            Date.newInstance(2026, 7, 4),
            'Leaving original'
        );
        insert new List<Opportunity>{ alreadyWon, toWin, staying, leaving };

        // Two Tasks exist from the two original Closed Won inserts.
        Set<Id> allIds = new Set<Id>{
            alreadyWon.Id,
            toWin.Id,
            staying.Id,
            leaving.Id
        };
        Assert.areEqual(2, getTasks(allIds).size());

        // Reset all Accounts so only a genuinely new handover can heat one.
        List<Account> accountsToReset = new List<Account>();
        for (Id accountId : new Set<Id>{
            alreadyWonAcc.Id,
            toWinAcc.Id,
            stayingAcc.Id,
            leavingAcc.Id
        }) {
            Account acc = getAccount(accountId);
            acc.Rating = 'Warm';
            accountsToReset.add(acc);
        }
        update accountsToReset;

        Opportunity alreadyWonUpdate = getOpportunity(alreadyWon.Id);
        alreadyWonUpdate.Name = 'Mixed already won - renamed';
        alreadyWonUpdate.NextStep = 'Already custom';

        Opportunity toWinUpdate = getOpportunity(toWin.Id);
        toWinUpdate.StageName = WON;
        toWinUpdate.CloseDate = Date.newInstance(2026, 7, 10);
        toWinUpdate.NextStep = 'To win custom';

        Opportunity stayingUpdate = getOpportunity(staying.Id);
        stayingUpdate.StageName = 'Qualification';
        stayingUpdate.NextStep = 'Staying custom';

        Opportunity leavingUpdate = getOpportunity(leaving.Id);
        leavingUpdate.StageName = 'Closed Lost';
        leavingUpdate.NextStep = 'Leaving custom';

        update new List<Opportunity>{
            alreadyWonUpdate,
            toWinUpdate,
            stayingUpdate,
            leavingUpdate
        };

        Assert.areEqual('Already custom', getOpportunity(alreadyWon.Id).NextStep);
        Assert.areEqual(HANDOVER, getOpportunity(toWin.Id).NextStep);
        Assert.areEqual('Staying custom', getOpportunity(staying.Id).NextStep);
        Assert.areEqual('Leaving custom', getOpportunity(leaving.Id).NextStep);

        List<Task> allTasks = getTasks(allIds);
        Assert.areEqual(
            3,
            allTasks.size(),
            'Only the Opportunity newly won in the mixed update may gain a Task.'
        );

        Map<Id, Integer> taskCountByOpp = new Map<Id, Integer>();
        for (Id oppId : allIds) {
            taskCountByOpp.put(oppId, 0);
        }
        Task toWinTask;
        for (Task task : allTasks) {
            taskCountByOpp.put(task.WhatId, taskCountByOpp.get(task.WhatId) + 1);
            if (task.WhatId == toWin.Id) {
                toWinTask = task;
            }
        }
        Assert.areEqual(1, taskCountByOpp.get(alreadyWon.Id));
        Assert.areEqual(1, taskCountByOpp.get(toWin.Id));
        Assert.areEqual(0, taskCountByOpp.get(staying.Id));
        Assert.areEqual(1, taskCountByOpp.get(leaving.Id));
        Assert.isTrue(toWinTask != null, 'The newly won Opportunity must have a Task.');
        assertKickoffTask(
            toWinTask,
            toWin.Id,
            getOpportunity(toWin.Id).OwnerId,
            Date.newInstance(2026, 7, 17)
        );

        Assert.areEqual('Warm', getAccount(alreadyWonAcc.Id).Rating);
        Assert.areEqual('Hot', getAccount(toWinAcc.Id).Rating);
        Assert.areEqual('Warm', getAccount(stayingAcc.Id).Rating);
        Assert.areEqual('Warm', getAccount(leavingAcc.Id).Rating);
    }

