public with sharing class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option() {
        }

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault == true;
        }
    }

    public class PicklistServiceException extends Exception {
    }

    /**
     * Returns the active picklist values for the specified field, in the
     * order they are defined on the field.
     *
     * @param objectApiName API name of the object (case-insensitive)
     * @param fieldApiName  API name of the picklist field (case-insensitive)
     * @return List of active options
     * @throws PicklistServiceException if either name is null or blank, the
     *         object or field does not exist, or the field is not a picklist
     *         or multi-select picklist
     */
    public static List<PicklistService.Option> activeOptions(
        String objectApiName,
        String fieldApiName
    ) {
        try {
            if (String.isBlank(objectApiName)) {
                throw new PicklistServiceException(
                    'Object API name must not be null or blank.'
                );
            }
            if (String.isBlank(fieldApiName)) {
                throw new PicklistServiceException(
                    'Field API name must not be null or blank.'
                );
            }

            String normalizedObjectName = objectApiName.trim();
            String normalizedFieldName = fieldApiName.trim();

            Schema.SObjectType sObjectType = null;
            Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
            for (String candidateObjectName : globalDescribe.keySet()) {
                if (candidateObjectName.equalsIgnoreCase(normalizedObjectName)) {
                    sObjectType = globalDescribe.get(candidateObjectName);
                    break;
                }
            }

            if (sObjectType == null) {
                throw new PicklistServiceException(
                    'Object does not exist: ' + objectApiName
                );
            }

            Schema.DescribeSObjectResult objectDescribe = sObjectType.getDescribe();
            Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();

            Schema.SObjectField sObjectField = null;
            for (String candidateFieldName : fieldMap.keySet()) {
                if (candidateFieldName.equalsIgnoreCase(normalizedFieldName)) {
                    sObjectField = fieldMap.get(candidateFieldName);
                    break;
                }
            }

            if (sObjectField == null) {
                throw new PicklistServiceException(
                    'Field does not exist on ' +
                    objectDescribe.getName() +
                    ': ' +
                    fieldApiName
                );
            }

            Schema.DescribeFieldResult fieldDescribe = sObjectField.getDescribe();
            Schema.DisplayType fieldType = fieldDescribe.getType();

            if (
                fieldType != Schema.DisplayType.Picklist &&
                fieldType != Schema.DisplayType.MultiPicklist
            ) {
                throw new PicklistServiceException(
                    'Field is not a picklist or multi-select picklist: ' +
                    objectDescribe.getName() +
                    '.' +
                    fieldDescribe.getName()
                );
            }

            List<PicklistService.Option> options = new List<PicklistService.Option>();
            for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
                if (entry.isActive()) {
                    options.add(
                        new PicklistService.Option(
                            entry.getValue(),
                            entry.getLabel(),
                            entry.isDefaultValue()
                        )
                    );
                }
            }
            return options;
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new PicklistServiceException(
                'Unable to retrieve picklist options for ' +
                objectApiName +
                '.' +
                fieldApiName +
                ': ' +
                e.getMessage()
            );
        }
    }
}
