public without sharing class ShipmentEventHandler {

    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        // Index by normalised order number; iterating in order and overwriting
        // ensures the last event for a given order wins.
        Map<String, FB_Shipment_Event__e> lastEventByOrderNumber =
            new Map<String, FB_Shipment_Event__e>();
        for (FB_Shipment_Event__e evt : events) {
            if (evt == null || String.isBlank(evt.Order_Number__c)) {
                continue;
            }
            lastEventByOrderNumber.put(evt.Order_Number__c.trim().toUpperCase(), evt);
        }

        if (lastEventByOrderNumber.isEmpty()) {
            return;
        }

        Date shippedDate = Date.today();
        List<FB_Sales_Order__c> ordersToUpdate = new List<FB_Sales_Order__c>();

        for (FB_Sales_Order__c orderRecord : [
            SELECT Id, Order_Number__c, Status__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :lastEventByOrderNumber.keySet()
        ]) {
            if (orderRecord.Status__c == 'Cancelled') {
                continue;
            }
            if (String.isBlank(orderRecord.Order_Number__c)) {
                continue;
            }
            FB_Shipment_Event__e evt =
                lastEventByOrderNumber.get(orderRecord.Order_Number__c.trim().toUpperCase());
            if (evt == null) {
                continue;
            }
            ordersToUpdate.add(new FB_Sales_Order__c(
                Id = orderRecord.Id,
                Status__c = 'Shipped',
                Tracking_Number__c = evt.Tracking_Number__c,
                Carrier__c = evt.Carrier__c,
                Shipped_Date__c = shippedDate
            ));
        }

        if (!ordersToUpdate.isEmpty()) {
            update ordersToUpdate;
        }
    }
}
