public class AccountScoringJob implements Queueable {
    private static final Integer MAX_ACCOUNTS_PER_EXECUTION = 200;
    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds == null
            ? new List<Id>()
            : new List<Id>(accountIds);
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    public void execute(QueueableContext context) {
        // The context is intentionally unused so that execute(null) is safe
        // when the job is invoked directly by tests.
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer currentSize = Math.min(
            MAX_ACCOUNTS_PER_EXECUTION,
            accountIds.size()
        );
        List<Id> currentIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();

        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < currentSize) {
                currentIds.add(accountIds[i]);
            } else {
                remainingIds.add(accountIds[i]);
            }
        }

        // The single SOQL query for this execution.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :currentIds
        ];

        for (Account account : accounts) {
            if (
                account.AnnualRevenue != null &&
                account.AnnualRevenue >= HOT_THRESHOLD
            ) {
                account.Rating = 'Hot';
            } else if (
                account.AnnualRevenue != null &&
                account.AnnualRevenue >= WARM_THRESHOLD
            ) {
                account.Rating = 'Warm';
            } else {
                account.Rating = 'Cold';
            }
        }

        // The single DML statement for this execution.
        if (!accounts.isEmpty()) {
            update accounts;
        }

        if (!remainingIds.isEmpty()) {
            // Enqueuing with a 0-minute delay resets the queueable stack
            // depth. This avoids the low chained-job stack-depth limit in
            // Developer Edition orgs (allowing 250 chained jobs for 50,000
            // accounts) while still executing promptly. Delayed queueable
            // jobs also execute synchronously under Test.stopTest(), so the
            // complete chain is processed within a single test execution.
            System.enqueueJob(new AccountScoringJob(remainingIds), 0);
        }
    }
}
