```apex
/**
 * Keeps Account.FB_Open_Pipeline__c and Account.FB_Open_Opportunities__c
 * in sync with the account's open opportunities.
 *
 * Recursion / re-entrancy strategy (deliberately NO static "has run" flag,
 * which would break a second DML on the same records in one transaction):
 *  1. On update, only recalculate when a pipeline-relevant field changed
 *     (Amount, IsClosed, AccountId). The Account trigger's rating-only
 *     opportunity updates therefore cause an immediate no-op exit and
 *     cannot start a Handler -> Account -> Opportunity -> Handler loop.
 *  2. Only update an Account when its calculated totals actually differ
 *     from its stored values, so a recalculation triggered by a rating
 *     change (or any redundant change) performs no Account DML at all.
 * Together these terminate the recursive chain after one harmless pass
 * while still recalculating correctly on every genuine DML statement.
 *
 * without sharing: a roll-up must count all open opportunities and update
 * the parent account regardless of the running user's record visibility.
 */
public without sharing class OpportunityPipelineHandler {

    public void onAfterInsert(List<Opportunity> newOpportunities) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newOpportunities) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public void onAfterUpdate(List<Opportunity> newOpportunities, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newOpportunities) {
            Opportunity oldOpp = oldMap.get(opp.Id);

            Boolean relevantChange =
                opp.Amount != oldOpp.Amount ||
                opp.IsClosed != oldOpp.IsClosed ||
                opp.AccountId != oldOpp.AccountId;

            if (relevantChange) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
                if (oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
            }
        }
        recalculate(accountIds);
    }

    public void onAfterDelete(List<Opportunity> oldOpportunities) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : oldOpportunities) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public void onAfterUndelete(List<Opportunity> newOpportunities) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newOpportunities) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        recalculate(accountIds);
    }

    private void recalculate(Set<Id> accountIds) {
        accountIds.remove(null);
        if (accountIds.isEmpty()) {
            return;
        }

        // Default every affected account to 0 / 0 so an account whose last
        // open opportunity went away (deleted, closed, moved, amount path)
        // shows 0 and 0 rather than blank or a stale total.
        Map<Id, Decimal> pipelineByAccountId = new Map<Id, Decimal>();
        Map<Id, Decimal> countByAccountId = new Map<Id, Decimal>();
        for (Id accountId : accountIds) {
            pipelineByAccountId.put(accountId, 0);
            countByAccountId.put(accountId, 0);
        }

        // Single bulk aggregate for all affected accounts.
        // SUM ignores null Amounts (blank counts as 0); if all Amounts are
        // null SUM returns null, which is coerced to 0 below.
        for (AggregateResult result : [
            SELECT AccountId accountId, SUM(Amount) totalAmount, COUNT(Id) openCount
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('accountId');
            Decimal totalAmount = (Decimal) result.get('totalAmount');
            Integer openCount = (Integer) result.get('openCount');

            pipelineByAccountId.put(accountId, totalAmount == null ? 0 : totalAmount);
            countByAccountId.put(accountId, Decimal.valueOf(openCount));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account account : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal newPipeline = pipelineByAccountId.get(account.Id);
            Decimal newCount = countByAccountId.get(account.Id);

            // Only write when the totals actually changed. This avoids
            // needless Account DML (and firing the Account trigger) and
            // guarantees the recursive chain terminates.
            if (account.FB_Open_Pipeline__c != newPipeline ||
                account.FB_Open_Opportunities__c != newCount) {
                account.FB_Open_Pipeline__c = newPipeline;
                account.FB_Open_Opportunities__c = newCount;
                accountsToUpdate.add(account);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
