```apex
/**
 * System maintenance job that purges old FB_Integration_Log__c records.
 *
 * Retention rules:
 *  - Non-ERROR logs (including logs with a blank Level__c) are deleted once
 *    they are more than 30 days old.
 *  - ERROR logs are deleted once they are more than 180 days old.
 *
 * `without sharing` is intentional: this is a system purge scheduled by an
 * admin/integration user and it must be able to delete stale logs regardless
 * of record ownership or sharing rules.
 *
 * The job deletes synchronously up to the per-transaction DML row limit so
 * small runs complete immediately, and delegates any remaining volume to a
 * batch run of itself so large backlogs do not hit governor limits.
 */
public without sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {

    private static final String JOB_NAME = 'Log purge (nightly)';
    private static final String CRON_EXP_DAILY_2AM = '0 0 2 * * ?';
    private static final String ERROR_LEVEL = 'ERROR';

    private static final Integer NON_ERROR_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;

    // Maximum number of rows that can be deleted in a single transaction.
    private static final Integer MAX_SYNC_DELETE_ROWS = 10000;
    private static final Integer BATCH_SIZE = 2000;

    public LogPurgeJob() {
    }

    /**
     * Schedules this job to run every day at 02:00.
     *
     * @return the Id (CronTrigger Id) returned by System.schedule.
     */
    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_EXP_DAILY_2AM, new LogPurgeJob());
    }

    // ------------------------------------------------------------------
    // Schedulable
    // ------------------------------------------------------------------

    public void execute(SchedulableContext context) {
        Datetime nonErrorCutoff = Datetime.now().addDays(-NON_ERROR_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);
        String errorLevel = ERROR_LEVEL;

        // Note: `Level__c != 'ERROR'` alone would not match blank levels in
        // SOQL, so null is checked explicitly to purge old blank/DEBUG/INFO logs.
        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :nonErrorCutoff AND (Level__c != :errorLevel OR Level__c = null))
               OR (CreatedDate < :errorCutoff AND Level__c = :errorLevel)
            LIMIT 10000
        ];

        if (!logsToDelete.isEmpty()) {
            // All-or-none = false so one undeletable record does not block the purge.
            Database.delete(logsToDelete, false);
        }

        // If the synchronous limit was reached there may be more records to
        // purge; hand the remainder to the batch implementation below.
        if (logsToDelete.size() == MAX_SYNC_DELETE_ROWS) {
            Database.executeBatch(new LogPurgeJob(), BATCH_SIZE);
        }
    }

    // ------------------------------------------------------------------
    // Database.Batchable<SObject> — used only for backlogs > 10,000 rows
    // ------------------------------------------------------------------

    public Database.QueryLocator start(Database.BatchableContext context) {
        Datetime nonErrorCutoff = Datetime.now().addDays(-NON_ERROR_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);
        String errorLevel = ERROR_LEVEL;

        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :nonErrorCutoff AND (Level__c != :errorLevel OR Level__c = null))
               OR (CreatedDate < :errorCutoff AND Level__c = :errorLevel)
        ]);
    }

    public void execute(Database.BatchableContext context, List<SObject> scope) {
        if (scope != null && !scope.isEmpty()) {
            Database.delete(scope, false);
        }
    }

    public void finish(Database.BatchableContext context) {
        // Nothing further to do once the purge completes.
    }
}
