public with sharing class OpportunityRollupService {

    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        for (Id accountId : accountIds) {
            result.put(accountId, 0);
        }

        Date startOfYear = Date.newInstance(Date.today().year(), 1, 1);
        Date startOfNextYear = startOfYear.addYears(1);

        for (AggregateResult agg : [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsWon = true
              AND CloseDate >= :startOfYear
              AND CloseDate < :startOfNextYear
            GROUP BY AccountId
            WITH USER_MODE
        ]) {
            Id accountId = (Id) agg.get('AccountId');
            if (!result.containsKey(accountId)) {
                continue;
            }
            Decimal totalAmount = (Decimal) agg.get('totalAmount');
            result.put(accountId, totalAmount == null ? 0 : totalAmount);
        }

        return result;
    }
}
