    private static List<Opportunity> captureRenewals(Integer expectedTimes) {
        fflib_ArgumentCaptor renewalCaptor = fflib_ArgumentCaptor.forClass(Opportunity.class);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, expectedTimes))
            .registerNew((Opportunity) renewalCaptor.capture());

        List<Opportunity> renewals = new List<Opportunity>();
        for (Object captured : renewalCaptor.getAllValues()) {
            renewals.add((Opportunity) captured);
        }
        return renewals;
    }

    private static List<Task> captureTasks(Integer expectedTimes) {
        fflib_ArgumentCaptor taskCaptor = fflib_ArgumentCaptor.forClass(Task.class);
        fflib_ArgumentCaptor parentCaptor = fflib_ArgumentCaptor.forClass(Opportunity.class);
        // Passing Task.WhatId literally also pins the related-to field used.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, expectedTimes))
            .registerNew((Task) taskCaptor.capture(), Task.WhatId, (Opportunity) parentCaptor.capture());

        List<Task> tasks = new List<Task>();
        for (Object captured : taskCaptor.getAllValues()) {
            tasks.add((Task) captured);
        }
        capturedTaskParents = new List<Opportunity>();
        for (Object captured : parentCaptor.getAllValues()) {
            capturedTaskParents.add((Opportunity) captured);
        }
        return tasks;
    }

    private static void verifyCommitWork(Integer expectedTimes) {
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, expectedTimes)).commitWork();
    }

