    static void weightedAmountByStage_givenMultipleStages_sumsPerOpportunityRoundedAmountsByStage() {
        Id accountId1 = fflib_IDGenerator.generate(Account.SObjectType);
        Id accountId2 = fflib_IDGenerator.generate(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountId1, accountId2 };

        List<Opportunity> opportunities = new List<Opportunity>{
            // 199.99 * 33 / 100 = 65.9967, rounded per opportunity to 66.00.
            // Two such opportunities must total 132.00, not the unrounded 131.99.
            makeOpportunity(accountId1, 'Prospecting', 199.99, 33),
            makeOpportunity(accountId2, 'Prospecting', 199.99, 33),
            // 10000 * 25 / 100 = 2500.00 and 5000 * 50 / 100 = 2500.00.
            makeOpportunity(accountId1, 'Qualification', 10000, 25),
            makeOpportunity(accountId2, 'Qualification', 5000, 50)
        };

        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock = stubSelector(mocks, accountIds, opportunities);

        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        Assert.isNotNull(result, 'Result map should not be null.');
        Assert.areEqual(2, result.size(), 'Result should contain exactly the two returned stages.');
        Assert.areEqual(
            132.00,
            result.get('Prospecting'),
            'Prospecting should sum the per-opportunity rounded weighted amounts.'
        );
        Assert.areEqual(
            5000.00,
            result.get('Qualification'),
