            ORIGINAL_DESCRIPTION,
            afterCutoff.Description,
            'Opportunity after the cutoff should be unchanged'
        );
        Assert.areEqual('Closed Won', closedWon.StageName, 'Closed Won opportunity should be unchanged');
        Assert.areEqual(ORIGINAL_DESCRIPTION, closedWon.Description, 'Closed Won opportunity should be unchanged');
        Assert.areEqual('Closed Lost', closedLost.StageName, 'Closed Lost opportunity should be unchanged');
        Assert.areEqual(ORIGINAL_DESCRIPTION, closedLost.Description, 'Closed Lost opportunity should be unchanged');

        verifyRegisterDirtyOnce(staleOne);
        verifyRegisterDirtyOnce(staleTwo);
        verifyRegisterDirtyNever(onCutoff);
        verifyRegisterDirtyNever(afterCutoff);
        verifyRegisterDirtyNever(closedWon);
        verifyRegisterDirtyNever(closedLost);
        verifyCommitOnce();
    }
