public with sharing class Opportunities extends fflib_SObjectDomain {
    private static final String CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> sObjectList) {
        super(sObjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    public override void onAfterInsert() {
        Set<Id> opportunityIds = new Set<Id>();

        for (Opportunity opportunityRecord : (List<Opportunity>) getRecords()) {
            if (opportunityRecord.StageName == CLOSED_WON) {
                opportunityIds.add(opportunityRecord.Id);
            }
        }

        startFulfilment(opportunityIds);
    }

    public override void onAfterUpdate(Map<Id, SObject> existingRecords) {
        Set<Id> opportunityIds = new Set<Id>();

        for (Opportunity opportunityRecord : (List<Opportunity>) getRecords()) {
            Opportunity existingOpportunity = (Opportunity) existingRecords.get(opportunityRecord.Id);

            if (
                opportunityRecord.StageName == CLOSED_WON &&
                existingOpportunity != null &&
                existingOpportunity.StageName != CLOSED_WON
            ) {
                opportunityIds.add(opportunityRecord.Id);
            }
        }

        startFulfilment(opportunityIds);
    }

    private void startFulfilment(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return;
        }

        IOpportunityFulfilmentService fulfilmentService =
            (IOpportunityFulfilmentService) Application.Service.newInstance(
                IOpportunityFulfilmentService.class
            );

        fulfilmentService.startFulfilment(opportunityIds);
    }
}
