public with sharing class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        fflib_ISObjectUnitOfWork unitOfWork =
            (fflib_ISObjectUnitOfWork) Application.UnitOfWork.newInstance();

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        Integer closedCount = 0;

        if (opportunities != null) {
            for (Opportunity opportunityRecord : opportunities) {
                if (opportunityRecord.StageName == 'Closed Won') {
                    continue;
                }

                opportunityRecord.StageName = 'Closed Won';
                opportunityRecord.CloseDate = Date.today();

                unitOfWork.registerDirty(opportunityRecord);

                // Deal_Won__e uses Publish Immediately, so it must not be
                // published before the Opportunity update succeeds.
                // registerPublishAfterSuccessTransaction makes fflib publish
                // the event from commitWork() only after all DML in that
                // commit has succeeded; if the DML throws, no event is
                // published and the exception propagates to the caller.
                unitOfWork.registerPublishAfterSuccessTransaction(
                    new Deal_Won__e(
                        Opportunity_Id__c = String.valueOf(opportunityRecord.Id),
                        Amount__c = opportunityRecord.Amount
                    )
                );

                closedCount++;
            }
        }

        unitOfWork.commitWork();

        return closedCount;
    }
}
