/**
 * Normalizes Contact phone numbers for the dialer.
 *
 * Deviations from the requested approach, and why:
 * 1. Keeping every '+' character, as in [^0-9+], would retain '+' characters
 *    in the middle of a number or multiple leading '+' characters. The dialer
 *    accepts digits with only a single leading '+', so only a leading '+' is
 *    preserved and all other '+' characters are removed.
 * 2. Contacts whose Phone is already normalized are not submitted to DML.
 *    Updating them would unnecessarily execute validation rules and
 *    automation, change LastModifiedDate, and could report an already
 *    compliant record as a failure. All contacts requiring a change are still
 *    saved together in one partial-success update after the loop.
 *
 * Implementation note: Database.SaveResult.getId() is null for a failed save,
 * so failures are keyed using the Id at the corresponding position in the
 * list submitted to Database.update.
 */
public with sharing class ContactPhoneCleanup {

    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failures = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return failures;
        }

        Set<Id> uniqueContactIds = new Set<Id>();
        for (Id contactId : contactIds) {
            if (contactId != null) {
                uniqueContactIds.add(contactId);
            }
        }

        if (uniqueContactIds.isEmpty()) {
            return failures;
        }

        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :uniqueContactIds
            WITH USER_MODE
        ];

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact contact : contacts) {
            if (String.isBlank(contact.Phone)) {
                continue;
            }

            String stripped = contact.Phone.replaceAll('[^0-9+]', '');
            Boolean hasLeadingPlus = stripped.startsWith('+');
            String digitsOnly = stripped.replace('+', '');

            String normalizedPhone;
            if (String.isEmpty(digitsOnly)) {
                normalizedPhone = '';
            } else if (hasLeadingPlus) {
                normalizedPhone = '+' + digitsOnly;
            } else {
                normalizedPhone = digitsOnly;
            }

            if (normalizedPhone == contact.Phone) {
                continue;
            }

            contact.Phone = normalizedPhone;
            contactsToUpdate.add(contact);
        }

        if (contactsToUpdate.isEmpty()) {
            return failures;
        }

        List<Database.SaveResult> results = Database.update(
            contactsToUpdate,
            false,
            AccessLevel.USER_MODE
        );

        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult result = results[i];

            if (!result.isSuccess()) {
                String errorMessage = result.getErrors().isEmpty()
                    ? 'Unknown error'
                    : result.getErrors()[0].getMessage();

                failures.put(contactsToUpdate[i].Id, errorMessage);
            }
        }

        return failures;
    }
}
