/**
 * Weekly pipeline totals for sales ops.
 *
 * Deliberately implemented differently from the requested
 * "one SUM query per stage inside a loop":
 * - A single aggregate query with GROUP BY StageName returns all four
 *   stage totals at once, using 1 SOQL query instead of 4.
 * - SOQL in a loop violates governor-limit best practice and static
 *   analysis rules even when the loop count is currently small; if the
 *   stage list grows, the loop version consumes more of the 100-query
 *   limit while this version still uses exactly one query.
 * - `with sharing` plus WITH USER_MODE ensures the totals only include
 *   opportunities and fields the running user is entitled to see.
 */
public with sharing class PipelineSummary {

    private static final List<String> OPEN_STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>();
        for (String stage : OPEN_STAGES) {
            totals.put(stage, 0);
        }

        // No valid inclusive range can match; still return all four 0 totals.
        if (fromDate == null || toDate == null || fromDate > toDate) {
            return totals;
        }

        // One bulk-safe query for all stages. SUM ignores null Amounts,
        // and stages with no matching rows are absent from the result,
        // leaving their pre-initialised 0 values in place.
        for (AggregateResult result : [
            SELECT StageName, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE StageName IN :OPEN_STAGES
              AND CloseDate >= :fromDate
              AND CloseDate <= :toDate
            WITH USER_MODE
            GROUP BY StageName
        ]) {
            String stage = (String) result.get('StageName');
            Decimal total = (Decimal) result.get('totalAmount');
            if (stage != null && totals.containsKey(stage)) {
                totals.put(stage, total == null ? 0 : total);
            }
        }

        return totals;
    }
}
