/**
 * Pushes newly created Accounts to the ERP as customers.
 *
 * Deviation from the ticket's "callout right from the trigger, one
 * request per account" (see note accompanying this delivery):
 *  - The callout runs in a Queueable job enqueued by the trigger,
 *    because a synchronous callout from a trigger runs against
 *    uncommitted work and cannot be performed.
 *  - Accounts are sent as one JSON array per batch (max 200, as per
 *    the API contract) instead of one request per account, because
 *    a 200-record insert would otherwise exceed the limit of 100
 *    callouts per transaction.
 *
 * Authentication is handled entirely by the Named Credential "ERP";
 * no credentials are stored in code.
 */
public class ErpCustomerSync implements Queueable, Database.AllowsCallouts {

    private static final String ENDPOINT = 'callout:ERP/api/customers';
    private static final Integer MAX_BATCH_SIZE = 200;

    private final List<CustomerPayload> payloads;

    /**
     * DTO matching the ERP contract. Field names are serialized
     * verbatim as the JSON keys.
     */
    public class CustomerPayload {
        public String salesforceId;
        public String name;
        public String country;

        public CustomerPayload(Account acc) {
            // String conversion of an Id yields the 18-character form.
            this.salesforceId = String.valueOf(acc.Id);
            this.name = acc.Name;
            // Blank must be sent as JSON null, not an empty string.
            this.country = String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry;
        }
    }

    public ErpCustomerSync(List<Account> accounts) {
        this.payloads = new List<CustomerPayload>();
        if (accounts != null) {
            for (Account acc : accounts) {
                if (acc.Id != null) {
                    this.payloads.add(new CustomerPayload(acc));
                }
            }
        }
    }

    /**
     * Called once from the after-insert trigger with the whole
     * Trigger.new batch. Enqueues a single Queueable job; all data
     * needed for the callout is taken from Trigger.new, so no SOQL
     * is required.
     */
    public static void enqueueSync(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }
        System.enqueueJob(new ErpCustomerSync(newAccounts));
    }

    public void execute(QueueableContext context) {
        if (payloads == null || payloads.isEmpty()) {
            return;
        }

        Http http = new Http();

        // Normally a single chunk: a trigger batch is at most 200
        // records. Chunking keeps this safe for any larger input too.
        for (Integer startIndex = 0; startIndex < payloads.size(); startIndex += MAX_BATCH_SIZE) {
            Integer endIndex = Math.min(startIndex + MAX_BATCH_SIZE, payloads.size());
            List<CustomerPayload> chunk = new List<CustomerPayload>();
            for (Integer i = startIndex; i < endIndex; i++) {
                chunk.add(payloads[i]);
            }

            HttpRequest request = new HttpRequest();
            request.setEndpoint(ENDPOINT);
            request.setMethod('POST');
            request.setHeader('Content-Type', 'application/json');
            // suppressApexObjectNulls = false so a blank country is
            // serialized explicitly as "country": null.
            request.setBody(JSON.serialize(chunk, false));

            // The ERP answers 202 Accepted. Per the ticket, error
            // handling and retries are intentionally out of scope,
            // so the response is not inspected here.
            http.send(request);
        }
    }
}
