/**
 * Publishes Deal_Stage_Change__e platform events for downstream consumers.
 *
 * DEVIATION FROM THE REQUESTED IMPLEMENTATION:
 * This class does not call EventBus.publish once per Opportunity inside
 * the loop. It builds the complete list of events and makes a single bulk
 * EventBus.publish(List<SObject>) call.
 *
 * This preserves the required behaviour because the bulk overload returns
 * one Database.SaveResult per submitted event, in the same order as the
 * events submitted, so callers can still identify exactly which event
 * failed by index.
 *
 * The bulk form is required for production use because it is bulk-safe,
 * avoids repeated publish calls and their overhead/governor consumption
 * for trigger-sized batches of up to 200 records (and larger inputs),
 * and follows Salesforce's platform-event publishing best practice.
 */
public with sharing class DealEventPublisher {

    /**
     * Publishes one Deal_Stage_Change__e event per supplied Opportunity.
     *
     * @param opportunities Opportunities whose stage changes are to be published.
     * @return Publish results in the same order as the input list. An empty
     *         list is returned when the input is null or empty, and no
     *         event is published in that case. For publish-after-commit
     *         events, a successful result means the event was accepted for
     *         publication on transaction commit, not that subscribers have
     *         already processed it.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>(opportunities.size());

        for (Opportunity opportunity : opportunities) {
            events.add(
                new Deal_Stage_Change__e(
                    // An Id converted to String in Apex is the 18-character form.
                    // The explicit null check also avoids String.valueOf(Id)
                    // producing the literal text 'null' for a null Id.
                    Opportunity_Id__c = (opportunity == null || opportunity.Id == null)
                        ? null
                        : String.valueOf(opportunity.Id),
                    Stage__c = opportunity?.StageName,
                    Amount__c = opportunity?.Amount
                )
            );
        }

        // Single bulk publish; results correspond 1:1 and in order with events.
        return EventBus.publish(events);
    }
}
