/**
 * Keeps Account.Rating in sync with the open Opportunity pipeline:
 *   Hot  - at least one open Opportunity with Amount >= 100,000
 *   Warm - at least one open Opportunity, none that large
 *   Cold - no open Opportunities
 */
public with sharing class AccountRatingService {

    private static final Decimal HOT_THRESHOLD = 100000;

    /**
     * Recalculates Rating for the given Accounts asynchronously.
     * Accepts a Set of Account Ids so callers can enqueue a single
     * future job for an entire transaction (bulk-safe for batches
     * of 200+ Opportunities).
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Set<Id> ids = new Set<Id>(accountIds);
        ids.remove(null);
        if (ids.isEmpty()) {
            return;
        }

        // One aggregate query for all Accounts: largest open Amount per Account.
        // Accounts absent from the result have no open Opportunities.
        Set<Id> accountsWithOpenOpps = new Set<Id>();
        Map<Id, Decimal> maxOpenAmountByAccountId = new Map<Id, Decimal>();

        for (AggregateResult result : [
            SELECT AccountId, MAX(Amount) maxAmount
            FROM Opportunity
            WHERE AccountId IN :ids
            AND IsClosed = false
            GROUP BY AccountId
            WITH SECURITY_ENFORCED
        ]) {
            Id accountId = (Id) result.get('AccountId');
            accountsWithOpenOpps.add(accountId);
            // MAX is null when every open Opportunity has a null Amount.
            maxOpenAmountByAccountId.put(accountId, (Decimal) result.get('maxAmount'));
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Account acc : [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :ids
            WITH SECURITY_ENFORCED
        ]) {
            String newRating;
            Decimal maxAmount = maxOpenAmountByAccountId.get(acc.Id);

            if (!accountsWithOpenOpps.contains(acc.Id)) {
                newRating = 'Cold';
            } else if (maxAmount != null && maxAmount >= HOT_THRESHOLD) {
                newRating = 'Hot';
            } else {
                newRating = 'Warm';
            }

            if (acc.Rating != newRating) {
                accountsToUpdate.add(new Account(Id = acc.Id, Rating = newRating));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
