/**
 * Applies the standard product discount to new OpportunityLineItems.
 *
 * DEVIATION FROM THE REQUESTED IMPLEMENTATION - AND WHY:
 * The request was to call PricingRules.standardDiscountFor(line.Product2Id)
 * inside the loop for each line. That overload of PricingRules performs its
 * own SOQL query on every invocation, so processing a 200-line CPQ quote
 * that way would issue up to 200 SOQL queries in one transaction and exceed
 * the per-transaction limit of 100 SOQL queries, causing the insert to fail.
 * Repeated lines for the same product would also re-query the same record.
 *
 * This handler therefore bulkifies the data retrieval instead: it collects
 * the distinct products for all lines that need a discount, fetches their
 * Family values with a single query (plus at most one query to resolve
 * products from PricebookEntryId when Product2Id is not yet populated in
 * before insert), and then delegates the actual discount decision for each
 * line to PricingRules.standardDiscountForFamily(String) - the public,
 * SOQL-free overload already exposed by the pricing team.
 *
 * This does NOT copy the pricing rules and does NOT modify PricingRules:
 * no family names and no discount percentages are hard-coded here; the
 * family-to-discount mapping remains solely in PricingRules, so if the
 * pricing team changes that mapping this handler picks it up automatically.
 * Longer term, the ideal fix would be for PricingRules to expose a bulk
 * overload (e.g. standardDiscountFor(Set<Id>)), but until then this uses
 * only its existing public API. Total SOQL per trigger chunk: at most 2,
 * regardless of how many lines or duplicate products are inserted.
 */
public with sharing class LineItemDiscountHandler {

    public static void beforeInsert(List<OpportunityLineItem> newLines) {
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        // Only lines with no discount typed in get the standard discount.
        // A Discount of 0 is an explicit value entered by the rep and is kept.
        List<OpportunityLineItem> linesNeedingDiscount = new List<OpportunityLineItem>();
        Set<Id> productIds = new Set<Id>();
        Set<Id> pricebookEntryIds = new Set<Id>();

        for (OpportunityLineItem line : newLines) {
            if (line.Discount != null) {
                continue;
            }
            linesNeedingDiscount.add(line);
            if (line.Product2Id != null) {
                productIds.add(line.Product2Id);
            } else if (line.PricebookEntryId != null) {
                // Product2Id is derived from the price book entry and may not
                // be populated on the record yet in before insert, so resolve
                // the product via PricebookEntryId in that case.
                pricebookEntryIds.add(line.PricebookEntryId);
            }
        }

        if (linesNeedingDiscount.isEmpty()) {
            return;
        }

        // Resolve products from price book entries where needed (1 query max).
        Map<Id, Id> productIdByEntryId = new Map<Id, Id>();
        if (!pricebookEntryIds.isEmpty()) {
            for (PricebookEntry entry : [
                SELECT Id, Product2Id
                FROM PricebookEntry
                WHERE Id IN :pricebookEntryIds
            ]) {
                if (entry.Product2Id != null) {
                    productIdByEntryId.put(entry.Id, entry.Product2Id);
                    productIds.add(entry.Product2Id);
                }
            }
        }

        // Fetch the Family for every distinct product in one bulk query.
        // This only retrieves data; it contains no pricing logic.
        Map<Id, String> familyByProductId = new Map<Id, String>();
        if (!productIds.isEmpty()) {
            for (Product2 product : [
                SELECT Id, Family
                FROM Product2
                WHERE Id IN :productIds
            ]) {
                familyByProductId.put(product.Id, product.Family);
            }
        }

        // Delegate every discount decision to PricingRules.
        for (OpportunityLineItem line : linesNeedingDiscount) {
            Id productId = line.Product2Id != null
                ? line.Product2Id
                : productIdByEntryId.get(line.PricebookEntryId);
            String family = productId != null ? familyByProductId.get(productId) : null;
            line.Discount = PricingRules.standardDiscountForFamily(family);
        }
    }
}
