public with sharing class LeadContactMatcher {

    /**
     * Returns, for each lead, the Id of the first contact with the same email.
     *
     * Why not a nested loop:
     * A nested loop is O(leads * contacts). At the stated maximum of
     * 3,000 x 3,000 that is up to 9,000,000 comparisons, and it repeats
     * trimming/case-normalisation on every comparison. That quadratic
     * CPU cost is charged against the Apex CPU governor limit (10s sync /
     * 60s async) shared with the rest of the import transaction, so it can
     * time out as volumes grow even though 3,000 sounds small.
     *
     * This implementation is O(leads + contacts): each email is normalised
     * exactly once, contacts are indexed in a Map (~3,000 puts), and each
     * lead is then a single O(1) lookup (~3,000 gets) — roughly 6,000
     * operations instead of 9,000,000, with deterministic first-match
     * semantics. No SOQL or DML is performed.
     *
     * Matching rules:
     * - Case-insensitive and ignores leading/trailing whitespace.
     * - A blank (null/empty/whitespace-only) email never matches.
     * - If several contacts share an email, the first in `contacts` wins.
     * - The result has the same size and order as `leads`, with null
     *   where there is no match.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> result = new List<Id>();
        if (leads == null) {
            return result;
        }

        // Index contacts by normalised email. Only the first contact for a
        // given email is kept, preserving `contacts` order precedence.
        Map<String, Id> firstContactIdByEmail = new Map<String, Id>();
        if (contacts != null) {
            for (Contact c : contacts) {
                if (c == null) {
                    continue;
                }
                String key = normalize(c.Email);
                if (key == null) {
                    continue;
                }
                if (!firstContactIdByEmail.containsKey(key)) {
                    firstContactIdByEmail.put(key, c.Id);
                }
            }
        }

        for (Lead l : leads) {
            if (l == null) {
                result.add(null);
                continue;
            }
            String key = normalize(l.Email);
            result.add(key == null ? null : firstContactIdByEmail.get(key));
        }
        return result;
    }

    /**
     * Returns the canonical form of an email for comparison, or null if
     * the email is blank (null, empty, or whitespace only) so that blank
     * emails can never match each other or anything else.
     */
    private static String normalize(String email) {
        if (email == null) {
            return null;
        }
        String normalized = email.trim().toLowerCase();
        return normalized.length() == 0 ? null : normalized;
    }
}
