public with sharing class CaseSurveyJob implements Queueable {

    private final List<Id> caseIds;

    public CaseSurveyJob(List<Id> caseIds) {
        Set<Id> uniqueCaseIds = new Set<Id>();
        if (caseIds != null) {
            uniqueCaseIds.addAll(caseIds);
        }
        uniqueCaseIds.remove(null);
        this.caseIds = new List<Id>(uniqueCaseIds);
    }

    public CaseSurveyJob(Set<Id> caseIds) {
        this(caseIds == null ? new List<Id>() : new List<Id>(caseIds));
    }

    public CaseSurveyJob(Id caseId) {
        this(caseId == null ? new List<Id>() : new List<Id>{ caseId });
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        List<Task> surveyTasks = new List<Task>();
        // Re-query for current data and re-validate eligibility at run time.
        for (Case surveyCase : [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
                AND IsClosed = true
                AND ContactId != null
            WITH USER_MODE
        ]) {
            surveyTasks.add(new Task(
                WhatId = surveyCase.Id,
                WhoId = surveyCase.ContactId,
                Subject = 'CSAT survey: ' + surveyCase.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status = 'Not Started'
            ));
        }

        if (surveyTasks.isEmpty()) {
            return;
        }

        // Partial-success insert: one failed Task must not block the rest.
        List<Database.SaveResult> results =
            Database.insert(surveyTasks, false, AccessLevel.USER_MODE);

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                List<String> errorMessages = new List<String>();
                for (Database.Error err : results[i].getErrors()) {
                    errorMessages.add(err.getStatusCode() + ': ' + err.getMessage());
                }
                System.debug(LoggingLevel.ERROR,
                    'CaseSurveyJob: failed to create survey Task for Case ' +
                    surveyTasks[i].WhatId + ' - ' + String.join(errorMessages, '; '));
            }
        }
    }
}
