public inherited sharing class AccountCountrySync {

    public static void handleAfterUpdate(
        List<Account> newAccounts,
        Map<Id, Account> oldAccountsById
    ) {
        if (newAccounts == null || newAccounts.isEmpty()
            || oldAccountsById == null || oldAccountsById.isEmpty()) {
            return;
        }

        // Only accounts whose BillingCountry actually changed.
        Map<Id, Account> changedAccountsById = new Map<Id, Account>();
        for (Account newAccount : newAccounts) {
            Account oldAccount = oldAccountsById.get(newAccount.Id);
            if (oldAccount == null) {
                continue;
            }
            if (newAccount.BillingCountry != oldAccount.BillingCountry) {
                changedAccountsById.put(newAccount.Id, newAccount);
            }
        }

        if (changedAccountsById.isEmpty()) {
            return;
        }

        // One selective query, outside any loop: contacts of changed accounts only.
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact contactRecord : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountsById.keySet()
        ]) {
            Account newAccount = changedAccountsById.get(contactRecord.AccountId);
            Account oldAccount = oldAccountsById.get(contactRecord.AccountId);
            if (newAccount == null || oldAccount == null) {
                continue;
            }

            Boolean shouldSync =
                String.isBlank(contactRecord.MailingCountry) ||
                contactRecord.MailingCountry == oldAccount.BillingCountry;

            if (shouldSync
                && contactRecord.MailingCountry != newAccount.BillingCountry) {
                contactRecord.MailingCountry = newAccount.BillingCountry;
                contactsToUpdate.add(contactRecord);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
