```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    errorMessage = null;

    debounceTimeoutId = null;
    latestRequestId = 0;

    handleChange(event) {
        const rawValue = event?.detail?.value ?? event?.target?.value ?? '';
        const searchTerm = String(rawValue).trim();

        this.cancelPendingSearch();

        if (searchTerm.length < MIN_SEARCH_LENGTH) {
            // Invalidate any in-flight request so its response cannot
            // repopulate results after they have been cleared.
            this.latestRequestId += 1;
            this.contacts = [];
            this.errorMessage = null;
            return;
        }

        this.debounceTimeoutId = setTimeout(() => {
            this.debounceTimeoutId = null;
            this.performSearch(searchTerm);
        }, DEBOUNCE_DELAY);
    }

    async performSearch(searchTerm) {
        const requestId = ++this.latestRequestId;

        try {
            const result = await searchContacts({ searchTerm });

            if (requestId !== this.latestRequestId) {
                return;
            }

            this.contacts = result ?? [];
            this.errorMessage = null;
        } catch (error) {
            if (requestId !== this.latestRequestId) {
                return;
            }

            this.contacts = [];
            this.errorMessage =
                error?.body?.message ?? error?.message ?? 'An unknown error occurred.';
        }
    }

    cancelPendingSearch() {
        if (this.debounceTimeoutId !== null) {
            clearTimeout(this.debounceTimeoutId);
            this.debounceTimeoutId = null;
        }
    }

    disconnectedCallback() {
        this.cancelPendingSearch();
        // Prevent an already in-flight response from updating a removed component.
        this.latestRequestId += 1;
    }
}
