    handleSubmit() {
        const editors = Array.from(
            this.template.querySelectorAll('c-line-item-editor')
        );

        // Validate every editor, even after one fails, so all errors show.
        const validity = editors.map((editor) => editor.validate());
        const allValid = validity.every(Boolean);

        if (allValid) {
            this.showError = false;
            const lines = editors.map((editor) => editor.getValue());
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines },
                    bubbles: true,
                    composed: true
                })
            );
        } else {
            this.showError = true;
        }
    }
}
