import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const PERSONAL_EMAIL_DOMAINS = [
    'gmail.com',
    'yahoo.com',
    'hotmail.com',
    'outlook.com'
];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleFullNameChange(event) {
        this.fullName = event.detail.value;
    }

    handleEmailChange(event) {
        this.email = event.detail.value;
    }

    handleCompanyChange(event) {
        this.company = event.detail.value;
    }

    async handleRegister() {
        const emailInput = this.template.querySelector(
            '[data-field="email"]'
        );

        const emailValue = this.email ? String(this.email).trim() : '';
        const domain = emailValue
            .toLowerCase()
            .split('@')
            .pop();

        if (emailInput) {
            if (PERSONAL_EMAIL_DOMAINS.includes(domain)) {
                emailInput.setCustomValidity(
                    'Use your work email address.'
                );
            } else {
                emailInput.setCustomValidity('');
            }
        }

        const inputs = this.template.querySelectorAll('lightning-input');
        let isValid = true;

        inputs.forEach((input) => {
            const reportedValidity = input.reportValidity();
            let fieldValid;

            if (typeof reportedValidity === 'boolean') {
                fieldValid = reportedValidity;
            } else if (
                input.validity &&
                typeof input.validity.valid === 'boolean'
            ) {
                fieldValid = input.validity.valid;
            } else {
                fieldValid = true;
            }

            if (
                !fieldValid ||
                (input.validity && input.validity.valid === false)
            ) {
                isValid = false;
            }
        });

        if (!isValid) {
            return;
        }

        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });

            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message: error.body.message,
                    variant: 'error'
                })
            );
        }
    }
}
