import { LightningElement, api } from 'lwc';

let instanceCount = 0;

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value;
    _activeIndex = -1;
    _optionIdPrefix;

    constructor() {
        super();
        instanceCount += 1;
        this._optionIdPrefix = `status-listbox-option-${instanceCount}`;
    }

    @api
    get options() {
        return this._options;
    }

    set options(value) {
        const previousActiveValue =
            this._activeIndex >= 0 &&
            this._activeIndex < this._options.length
                ? this._options[this._activeIndex].value
                : undefined;

        this._options = Array.isArray(value) ? value : [];

        if (this._options.length === 0) {
            this._activeIndex = -1;
            return;
        }

        // Preserve the active option if it still exists in the new
        // options array (e.g. a new array identity with the same values).
        if (previousActiveValue !== undefined) {
            const previousIndex = this._options.findIndex(
                (option) => option.value === previousActiveValue
            );
            if (previousIndex !== -1) {
                this._activeIndex = previousIndex;
                return;
            }
        }

        this._syncActiveToValue();
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value;
        this._syncActiveToValue();
    }

    _syncActiveToValue() {
        if (!this._options || this._options.length === 0) {
            this._activeIndex = -1;
            return;
        }
        const selectedIndex = this._options.findIndex(
            (option) => option.value === this._value
        );
        this._activeIndex = selectedIndex === -1 ? 0 : selectedIndex;
    }

    get activeId() {
        if (
            this._activeIndex < 0 ||
            !this._options ||
            this._activeIndex >= this._options.length
        ) {
            return undefined;
        }
        return `${this._optionIdPrefix}-${this._activeIndex}`;
    }

    get renderedOptions() {
        return (this._options || []).map((option, index) => ({
            label: option.label,
            value: option.value,
            index,
            id: `${this._optionIdPrefix}-${index}`,
            ariaSelected: option.value === this._value ? 'true' : 'false'
        }));
    }

    handleKeyDown(event) {
        const count = this._options ? this._options.length : 0;

        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                if (count > 0) {
                    this._activeIndex =
                        this._activeIndex < 0
                            ? 0
                            : Math.min(this._activeIndex + 1, count - 1);
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (count > 0) {
                    this._activeIndex =
                        this._activeIndex < 0
                            ? 0
                            : Math.max(this._activeIndex - 1, 0);
                }
                break;
            case 'Home':
                event.preventDefault();
                if (count > 0) {
                    this._activeIndex = 0;
                }
                break;
            case 'End':
                event.preventDefault();
                if (count > 0) {
                    this._activeIndex = count - 1;
                }
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this._selectActive();
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const indexAttribute = event.currentTarget.dataset.index;
        let index =
            indexAttribute !== undefined ? Number(indexAttribute) : -1;

        if (
            !Number.isInteger(index) ||
            index < 0 ||
            index >= this._options.length
        ) {
            const clickedValue = event.currentTarget.dataset.value;
            index = this._options.findIndex(
                (option) => option.value === clickedValue
            );
        }

        if (index < 0 || index >= this._options.length) {
            return;
        }

        this._activeIndex = index;
        this._selectValue(this._options[index].value);
    }

    _selectActive() {
        if (
            this._activeIndex < 0 ||
            !this._options ||
            this._activeIndex >= this._options.length
        ) {
            return;
        }
        this._selectValue(this._options[this._activeIndex].value);
    }

    _selectValue(value) {
        if (value === this._value) {
            return;
        }
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value },
                bubbles: true,
                composed: true
            })
        );
    }
