/**
 * Sets donors' current employers using NPSP's standard Primary Affiliation
 * mechanism.
 *
 * NPSP (via its Contact Primary Affiliation TDTM handler) maintains the
 * underlying npe5__Affiliation__c records when
 * Contact.npsp__Primary_Affiliation__c changes:
 *  - it creates the affiliation to the new organisation, or promotes an
 *    existing affiliation to that organisation, as Current and Primary;
 *  - it ends the previous primary affiliation as Former and non-primary,
 *    with an end date of today.
 *
 * Because that standard mechanism is used, this class deliberately:
 *  - does NOT create or update Affiliation records directly (which would
 *    risk duplicates and would fight NPSP's own automation);
 *  - does NOT touch Contact.AccountId, so each contact remains in their
 *    Household Account — the employer is recorded only through the
 *    Primary Affiliation lookup.
 *
 * Bulk behaviour: at most 1 SOQL query and 1 DML statement, regardless of
 * how many contacts are supplied (tested to 200). Contacts whose primary
 * affiliation already points at the requested organisation are not
 * updated at all, so no duplicate affiliation is created.
 */
public with sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Ignore unusable entries rather than clearing an employer by accident.
        Map<Id, Id> desiredEmployerByContactId = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id employerId = employerByContactId.get(contactId);
            if (contactId != null && employerId != null) {
                desiredEmployerByContactId.put(contactId, employerId);
            }
        }
        if (desiredEmployerByContactId.isEmpty()) {
            return;
        }

        // Single query: fetch only the field needed to decide what changes.
        // Nonexistent Contact Ids are simply not returned and are ignored.
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact contactRecord : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :desiredEmployerByContactId.keySet()
            WITH SECURITY_ENFORCED
        ]) {
            Id employerId = desiredEmployerByContactId.get(contactRecord.Id);
            // Idempotency: already the primary affiliation -> change nothing.
            if (contactRecord.npsp__Primary_Affiliation__c != employerId) {
                contactsToUpdate.add(new Contact(
                    Id = contactRecord.Id,
                    npsp__Primary_Affiliation__c = employerId
                ));
            }
        }

        // Single DML statement. Updating only the Primary Affiliation lookup
        // lets NPSP create/promote the new Current primary affiliation and
        // end the previous one (Former, non-primary, EndDate = today),
        // while AccountId — the Household Account — is left untouched.
        if (!contactsToUpdate.isEmpty()) {
            update as user contactsToUpdate;
        }
    }
}
