public class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> createdIds = new List<Id>();

        if (requests == null || requests.isEmpty()) {
            return createdIds;
        }

        // Validate every request before any DML (and before SOQL).
        Set<Id> contactIds = new Set<Id>();
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest request = requests[i];

            if (request == null) {
                throw new RecurringGiftException('Gift request at index ' + i + ' is null.');
            }
            if (request.contactId == null) {
                throw new RecurringGiftException('Gift request at index ' + i + ' has no contact.');
            }
            if (request.amount == null || request.amount <= 0) {
                throw new RecurringGiftException('Gift request at index ' + i + ' must have a positive amount.');
            }
            if (request.dayOfMonth == null || request.dayOfMonth < 1 || request.dayOfMonth > 31) {
                throw new RecurringGiftException('Gift request at index ' + i + ' has a day of month outside 1-31.');
            }
            if (request.startDate == null) {
                throw new RecurringGiftException('Gift request at index ' + i + ' has no start date.');
            }
            if (request.installments != null && request.installments < 0) {
                throw new RecurringGiftException('Gift request at index ' + i + ' has a negative number of installments.');
            }

            contactIds.add(request.contactId);
        }

        // Single SOQL query: resolve each donor's account (household/organization)
        // for npe03__Organization__c.
        Map<Id, Id> accountIdByContactId = new Map<Id, Id>();
        if (!contactIds.isEmpty()) {
            for (Contact donor : [
                SELECT Id, AccountId
                FROM Contact
                WHERE Id IN :contactIds
            ]) {
                if (donor.AccountId != null) {
                    accountIdByContactId.put(donor.Id, donor.AccountId);
                }
            }
        }

        // Optional Enhanced RD field for the planned installment count, if this
        // NPSP version exposes it as a writable field.
        String plannedInstallmentsField = findPlannedInstallmentsField();

        List<npe03__Recurring_Donation__c> donations = new List<npe03__Recurring_Donation__c>();

        for (GiftRequest request : requests) {
            Boolean isOpenEnded = (request.installments == null || request.installments == 0);
            Boolean useLastDayOfMonth = (request.dayOfMonth == 31);

            Date firstInstallmentDate = getFirstInstallmentDate(request, useLastDayOfMonth);
            Date endDate = isOpenEnded
                ? null
                : getLastInstallmentDate(request, useLastDayOfMonth, firstInstallmentDate);

            npe03__Recurring_Donation__c donation = new npe03__Recurring_Donation__c(
                npe03__Contact__c = request.contactId,
                npe03__Organization__c = accountIdByContactId.get(request.contactId),
                npe03__Amount__c = request.amount,
                npe03__Installment_Period__c = 'Monthly',
                npe03__Installments__c = isOpenEnded ? 0 : request.installments,
                npe03__Schedule_Type__c = 'Multiply By',
                npe03__Open_Ended_Status__c = 'Open',
                npe03__Date_Established__c = request.startDate,
                npe03__Next_Payment_Date__c = firstInstallmentDate,
                npsp__RecurringType__c = isOpenEnded ? 'Open' : 'Fixed',
                npsp__InstallmentFrequency__c = 1,
                npsp__Day_of_Month__c = String.valueOf(request.dayOfMonth),
                npsp__Always_Use_Last_Day_Of_Month__c = useLastDayOfMonth,
                npsp__StartDate__c = request.startDate,
                npsp__EndDate__c = endDate,
                npsp__Status__c = 'Active',
                npsp__PaymentMethod__c = request.paymentMethod
            );

            if (plannedInstallmentsField != null) {
                donation.put(
                    plannedInstallmentsField,
                    isOpenEnded ? null : (Object) request.installments
                );
            }

            donations.add(donation);
        }

        // Single DML statement. NPSP Enhanced Recurring Donations creates the
        // installment Opportunities itself; none are created here.
        insert donations;

        for (npe03__Recurring_Donation__c donation : donations) {
            createdIds.add(donation.Id);
        }
        return createdIds;
    }

    private static Date getFirstInstallmentDate(GiftRequest request, Boolean useLastDayOfMonth) {
        Date candidate = installmentDateInMonth(
            request.startDate.year(),
            request.startDate.month(),
            0,
            request.dayOfMonth,
            useLastDayOfMonth
        );
        if (candidate < request.startDate) {
            candidate = installmentDateInMonth(
                request.startDate.year(),
                request.startDate.month(),
                1,
                request.dayOfMonth,
                useLastDayOfMonth
            );
        }
        return candidate;
    }

    private static Date getLastInstallmentDate(
        GiftRequest request,
        Boolean useLastDayOfMonth,
        Date firstInstallmentDate
    ) {
        // firstInstallmentDate is in the start month or the following month.
        Integer firstOffset =
            (firstInstallmentDate.year() == request.startDate.year()
                && firstInstallmentDate.month() == request.startDate.month())
                ? 0
                : 1;
        Integer lastOffset = firstOffset + request.installments - 1;

        return installmentDateInMonth(
            request.startDate.year(),
            request.startDate.month(),
            lastOffset,
            request.dayOfMonth,
            useLastDayOfMonth
        );
    }

    private static Date installmentDateInMonth(
        Integer baseYear,
        Integer baseMonth,
        Integer monthOffset,
        Integer dayOfMonth,
        Boolean useLastDayOfMonth
    ) {
        Integer totalMonths = (baseYear * 12 + (baseMonth - 1) + monthOffset);
        Integer year = totalMonths / 12;
        Integer month = Math.mod(totalMonths, 12) + 1;
        Integer day = useLastDayOfMonth
            ? Date.daysInMonth(year, month)
            : Math.min(dayOfMonth, Date.daysInMonth(year, month));
        return Date.newInstance(year, month, day);
    }

    private static String findPlannedInstallmentsField() {
        Map<String, Schema.SObjectField> fieldMap =
            npe03__Recurring_Donation__c.SObjectType.getDescribe().fields.getMap();

        List<String> candidates = new List<String>{
            'npsp__NumberOfPlannedInstallments__c',
            'npsp__Number_of_Planned_Installments__c'
        };

        for (String candidate : candidates) {
            for (String fieldName : fieldMap.keySet()) {
                if (fieldName.equalsIgnoreCase(candidate)) {
                    Schema.DescribeFieldResult describe = fieldMap.get(fieldName).getDescribe();
                    if (describe.isCreateable() && !describe.isCalculated()) {
                        return describe.getName();
                    }
                }
            }
        }
        return null;
    }
}
