public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * Replaces all GAU Allocations for an Opportunity with percentage-based allocations.
     *
     * Only npsp__Percent__c is populated (npsp__Amount__c is deliberately left null).
     * NPSP derives the Amount from the Percent and the Opportunity Amount, and
     * recalculates it automatically when the Opportunity Amount later changes,
     * so no additional code is needed to keep the amounts correct.
     *
     * All validation is performed before any DML, so a failure leaves the
     * existing allocations untouched.
     */
    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        // ---------- Validation (before changing any data) ----------

        if (opportunityId == null) {
            throw new AllocationException('An Opportunity Id is required.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU allocation is required.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('A GAU Id is required for every allocation.');
            }
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null || percent <= 0) {
                throw new AllocationException(
                    'Allocation percentage for GAU ' + gauId + ' must be greater than 0.'
                );
            }
            totalPercent += percent;
        }

        if (totalPercent > 100) {
            throw new AllocationException(
                'Allocation percentages must not add up to more than 100%. Total was ' +
                totalPercent +
                '%.'
            );
        }

        // Every referenced GAU must exist and be active.
        Map<Id, npsp__General_Accounting_Unit__c> gauById =
            new Map<Id, npsp__General_Accounting_Unit__c>([
                SELECT Id, Name, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :percentByGauId.keySet()
                WITH USER_MODE
            ]);

        if (gauById.size() != percentByGauId.size()) {
            throw new AllocationException('One or more specified GAUs could not be found.');
        }

        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gauById.get(gauId);
            if (gau.npsp__Active__c != true) {
                throw new AllocationException(
                    'GAU "' + gau.Name + '" (' + gau.Id + ') is inactive.'
                );
            }
        }

        // The Opportunity must exist.
        List<Opportunity> opportunities = [
            SELECT Id
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
            LIMIT 1
        ];
        if (opportunities.isEmpty()) {
            throw new AllocationException('Opportunity ' + opportunityId + ' could not be found.');
        }

        // ---------- Replace existing allocations ----------

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
            WITH USER_MODE
        ];
        if (!existingAllocations.isEmpty()) {
            delete as user existingAllocations;
        }

        List<npsp__Allocation__c> allocationsToInsert = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            allocationsToInsert.add(
                new npsp__Allocation__c(
                    npsp__Opportunity__c = opportunityId,
                    npsp__General_Accounting_Unit__c = gauId,
                    npsp__Percent__c = percentByGauId.get(gauId)
                    // npsp__Amount__c intentionally not set: NPSP calculates it
                    // from the Percent and keeps it in sync with the Opportunity Amount.
                )
            );
        }

        insert as user allocationsToInsert;

        // Re-query so the returned records reflect the Amount that NPSP
        // calculated from each Percent during insert.
        Map<Id, npsp__Allocation__c> insertedById =
            new Map<Id, npsp__Allocation__c>([
                SELECT
                    Id,
                    npsp__Opportunity__c,
                    npsp__General_Accounting_Unit__c,
                    npsp__Amount__c,
                    npsp__Percent__c,
                    npsp__Payment__c,
                    npsp__Campaign__c,
                    npsp__Recurring_Donation__c
                FROM npsp__Allocation__c
                WHERE Id IN :new Map<Id, npsp__Allocation__c>(allocationsToInsert).keySet()
                WITH USER_MODE
            ]);

        List<npsp__Allocation__c> result = new List<npsp__Allocation__c>();
        for (npsp__Allocation__c inserted : allocationsToInsert) {
            result.add(insertedById.get(inserted.Id));
        }
        return result;
    }
}
