public with sharing class HouseholdService {

    private static final String HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME = 'HH_Account';

    /**
     * Creates one NPSP Household Account containing all supplied contacts.
     *
     * The primary contact is inserted first, without an AccountId. In the
     * Household Account model NPSP creates exactly one Household Account for
     * that contact, names the household and generates its greetings. The
     * remaining contacts are then inserted directly into that same household,
     * so no contact ever causes NPSP to create an additional household and
     * no empty or orphaned household is left behind.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty.');
        }
        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException('members must not contain null contacts.');
            }
        }

        Contact primaryContact = members[0];

        // Let NPSP create the household for the primary contact. Do not
        // create an Account first and do not assign an Account name here:
        // a pre-created Account would require a name, which would interfere
        // with NPSP automatic household naming.
        insert primaryContact;

        Id householdAccountId = primaryContact.AccountId;
        if (householdAccountId == null) {
            // NPSP creates the household from a Contact after-trigger and
            // updates the Contact in the database, so the in-memory Contact
            // may not yet show the new AccountId.
            List<Contact> insertedPrimary = [
                SELECT AccountId
                FROM Contact
                WHERE Id = :primaryContact.Id
                LIMIT 1
            ];
            if (!insertedPrimary.isEmpty()) {
                householdAccountId = insertedPrimary[0].AccountId;
            }
        }

        if (householdAccountId == null) {
            // Defensive fallback for an org in which NPSP automatic account
            // creation has been disabled. Create the one household explicitly
            // (record type resolved by DeveloperName, never a hard-coded Id)
            // and move the already-inserted primary contact into it. All DML
            // is in this transaction, so a failure still leaves nothing behind.
            householdAccountId = createHouseholdAccount();
            primaryContact.AccountId = householdAccountId;
            update primaryContact;
        } else {
            primaryContact.AccountId = householdAccountId;
        }

        // Insert every remaining member straight into the same household so
        // NPSP does not create a household for any of them.
        List<Contact> otherMembers = new List<Contact>();
        for (Integer i = 1; i < members.size(); i++) {
            members[i].AccountId = householdAccountId;
            otherMembers.add(members[i]);
        }
        if (!otherMembers.isEmpty()) {
            insert otherMembers;
        }

        // Guarantee the first contact is recorded as the household's primary
        // contact, without an unnecessary update when NPSP already set it.
        Account household = [
            SELECT npe01__One2OneContact__c
            FROM Account
            WHERE Id = :householdAccountId
        ];
        if (household.npe01__One2OneContact__c != primaryContact.Id) {
            household.npe01__One2OneContact__c = primaryContact.Id;
            update household;
        }

        return householdAccountId;
    }

    private static Id createHouseholdAccount() {
        Schema.RecordTypeInfo householdRecordType = Schema.SObjectType.Account
            .getRecordTypeInfosByDeveloperName()
            .get(HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME);
        Id householdRecordTypeId = householdRecordType == null
            ? null
            : householdRecordType.getRecordTypeId();

        // No name is set: NPSP household naming supplies it once the primary
        // contact is linked. The catch only supplies a temporary value if the
        // platform requires one because NPSP naming is inactive in this org;
        // NPSP renames the household when the primary contact is linked.
        Account household = new Account(RecordTypeId = householdRecordTypeId);
        try {
            insert household;
        } catch (DmlException nameRequired) {
            household = new Account(
                RecordTypeId = householdRecordTypeId,
                Name = 'Household'
            );
            insert household;
        }
        return household.Id;
    }
}
