public with sharing class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Map<Id, Id> validPairs = new Map<Id, Id>();
        Set<Id> allContactIds = new Set<Id>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            validPairs.put(childId, parentId);
            allContactIds.add(childId);
            allContactIds.add(parentId);
        }

        if (validPairs.isEmpty()) {
            return;
        }

        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c existing : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
            AND npe4__RelatedContact__c IN :allContactIds
        ]) {
            if (existing.npe4__Contact__c != null && existing.npe4__RelatedContact__c != null) {
                existingPairs.add(pairKey(existing.npe4__Contact__c, existing.npe4__RelatedContact__c));
            }
        }

        List<npe4__Relationship__c> relationshipsToCreate = new List<npe4__Relationship__c>();

        for (Id childId : validPairs.keySet()) {
            Id parentId = validPairs.get(childId);

            // Skip if any relationship already connects this pair in either direction.
            if (existingPairs.contains(pairKey(childId, parentId)) ||
                existingPairs.contains(pairKey(parentId, childId))) {
                continue;
            }

            // Create only the child's view of the relationship. NPSP's reciprocal
            // automation (List Setting) creates and links the reverse record,
            // resolving its type from the 'Parent' Relationship Lookup as
            // Son, Daughter or Child based on the child Contact. Creating the
            // reverse record here as well would produce duplicates.
            relationshipsToCreate.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));
        }

        if (!relationshipsToCreate.isEmpty()) {
            insert relationshipsToCreate;
        }
    }

    private static String pairKey(Id firstId, Id secondId) {
        return String.valueOf(firstId) + '|' + String.valueOf(secondId);
    }
}
