/**
 * TDTM handler that creates a follow-up Task for major Closed Won gifts.
 *
 * Registered by an admin via NPSP Settings > Trigger Configuration
 * (Trigger_Handler__c: Class = OPP_MajorGiftFollowUp_TDTM, Object = Opportunity,
 * Trigger Action = AfterInsert;AfterUpdate, Load Order = 5, Active = true,
 * Asynchronous = false). NPSP's TDTM dispatcher instantiates and calls this
 * class; deactivating that Trigger Handler record stops it running.
 * No Apex trigger is (or should be) defined for this handler.
 *
 * No SOQL and no direct DML are performed here: resulting Tasks are returned
 * in the TDTM DmlWrapper for the dispatcher to insert, so the handler is
 * bulk-safe for 200 records well within governor limits.
 */
global class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final String CLOSED_WON_STAGE = 'Closed Won';
    private static final String TASK_SUBJECT = 'Major gift thank-you call';

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }
        if (
            triggerAction != npsp.TDTM_Runnable.Action.AfterInsert &&
            triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate
        ) {
            return dmlWrapper;
        }

        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>();
        if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate && oldlist != null) {
            for (SObject record : oldlist) {
                Opportunity oldOpp = (Opportunity) record;
                if (oldOpp.Id != null) {
                    oldMap.put(oldOpp.Id, oldOpp);
                }
            }
        }

        for (SObject record : newlist) {
            Opportunity opp = (Opportunity) record;

            if (!isMajorClosedWon(opp)) {
                continue;
            }

            // On update, do not create another Task if the Opportunity
            // already qualified before this edit.
            if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
                Opportunity oldOpp = oldMap.get(opp.Id);
                if (oldOpp != null && isMajorClosedWon(oldOpp)) {
                    continue;
                }
            }

            dmlWrapper.objectsToInsert.add(
                new Task(
                    Subject = TASK_SUBJECT,
                    Priority = 'High',
                    Status = 'Not Started',
                    WhatId = opp.Id,
                    WhoId = opp.npsp__Primary_Contact__c,
                    OwnerId = opp.OwnerId,
                    ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(3) : null
                )
            );
        }

        return dmlWrapper;
    }

    private static Boolean isMajorClosedWon(Opportunity opp) {
        return opp != null &&
            opp.StageName == CLOSED_WON_STAGE &&
            opp.Amount != null &&
            opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }
}
