```apex
public with sharing class RecordAccessService {

    // UserRecordAccess SOQL queries can evaluate at most 200 distinct
    // RecordIds in a single query. Larger sets throw a QueryException,
    // so the input must be processed in batches of 200 or fewer.
    // For the maximum supported input of 2,000 Ids this results in
    // at most 10 SOQL queries, within the 20-query budget.
    private static final Integer USER_RECORD_ACCESS_BATCH_SIZE = 200;

    /**
     * Returns the subset of {@code recordIds} that the running user can
     * edit, as reported by UserRecordAccess.HasEditAccess. This takes
     * object permissions, ownership, sharing rules, the role hierarchy,
     * and View All / Modify All into account because UserRecordAccess
     * is computed by Salesforce from all of those mechanisms.
     *
     * The Ids may belong to different objects; UserRecordAccess works
     * across objects, so no per-object handling is required.
     *
     * @param recordIds Ids to check; may be null or contain nulls.
     * @return Ids the running user can edit; never null.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        // Copy to a List for slicing into batches, ignoring any nulls.
        List<Id> idsToCheck = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                idsToCheck.add(recordId);
            }
        }
        if (idsToCheck.isEmpty()) {
            return editable;
        }

        Id runningUserId = UserInfo.getUserId();

        // Bounded loop: at most ceil(2000 / 200) = 10 queries per call.
        // SOQL in this loop is intentional and safe because the batch
        // size and the maximum input size are both fixed and small.
        for (Integer start = 0; start < idsToCheck.size(); start += USER_RECORD_ACCESS_BATCH_SIZE) {
            Integer finish = Math.min(start + USER_RECORD_ACCESS_BATCH_SIZE, idsToCheck.size());

            List<Id> batch = new List<Id>();
            for (Integer i = start; i < finish; i++) {
                batch.add(idsToCheck[i]);
            }

            // A UserRecordAccess query must filter by a single UserId and
            // by RecordId. HasEditAccess is checked in Apex rather than in
            // the WHERE clause; Salesforce returns one row per requested
            // record (where determinable), with the access flags populated.
            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :runningUserId
                AND RecordId IN :batch
            ]) {
                if (access.HasEditAccess == true) {
                    editable.add(access.RecordId);
                }
            }
        }

        return editable;
    }
}
