public with sharing class EmployeeDirectoryService {
    /**
     * Returns the FB_Employee__c records visible to the running user
     * through sharing, ordered by Name ascending.
     *
     * Only custom fields that the running user can read are queried.
     * Inaccessible fields are therefore absent from the returned
     * records rather than present with a null value, and users with
     * partial field access do not cause an exception. If the user
     * cannot read the object at all, an empty list is returned.
     */
    public static List<FB_Employee__c> getDirectory() {
        Schema.DescribeSObjectResult objectDescribe =
            Schema.SObjectType.FB_Employee__c.getDescribe();

        if (!objectDescribe.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Build the SELECT list only from hard-coded field names that
        // the running user is permitted to read. Fields that are not
        // selected are not populated on the returned records.
        List<String> selectFields = new List<String>{ 'Id', 'Name' };

        if (Schema.SObjectType.FB_Employee__c.fields.Department__c.isAccessible()) {
            selectFields.add('Department__c');
        }
        if (Schema.SObjectType.FB_Employee__c.fields.Salary__c.isAccessible()) {
            selectFields.add('Salary__c');
        }
        if (Schema.SObjectType.FB_Employee__c.fields.Personal_Email__c.isAccessible()) {
            selectFields.add('Personal_Email__c');
        }

        // The query string contains no user input, so there is no
        // SOQL injection risk. The class is `with sharing`, so record
        // sharing for the running user is respected.
        String soql =
            'SELECT ' +
            String.join(selectFields, ', ') +
            ' FROM FB_Employee__c ORDER BY Name ASC';

        return (List<FB_Employee__c>) Database.query(soql);
    }
}
