File: force-app/main/default/classes/AccountOwnershipService.cls
```apex
public inherited sharing class AccountOwnershipService {
    /**
     * Reassigns the given Accounts and all of their Contacts to a new owner.
     *
     * Account trigger actions are bypassed for this ownership change only,
     * using the Trigger Actions Framework transaction (sObject) bypass.
     * Contact trigger actions run normally.
     *
     * DML is all-or-none and any exception propagates to the caller.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                accountsToUpdate.add(
                    new Account(Id = accountId, OwnerId = newOwnerId)
                );
            }
        }
        if (accountsToUpdate.isEmpty()) {
            return;
        }

        // Transaction bypass for the whole Account sObject only.
        // Use TriggerBase directly: MetadataTriggerHandler.bypass(...)
        // would bypass a named action, not the Account object.
        TriggerBase.bypass(Account.SObjectType);
        try {
            update accountsToUpdate;
        } finally {
            // Restore normal Account automation even if the update fails.
            TriggerBase.clearBypass(Account.SObjectType);
        }

        // Account bypass is already cleared, so Contact actions (and any
        // automation they invoke) run normally.
        List<Contact> contactsToUpdate = [
            SELECT Id
            FROM Contact
            WHERE AccountId IN :accountIds
        ];
        for (Contact contactToUpdate : contactsToUpdate) {
            contactToUpdate.OwnerId = newOwnerId;
        }
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
