public without sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String DUPLICATE_EMAIL_ERROR =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        preventDuplicateEmails((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Contact> oldContactsById = new Map<Id, Contact>(
            (List<Contact>) triggerOld
        );
        preventDuplicateEmails((List<Contact>) triggerNew, oldContactsById);
    }

    private void preventDuplicateEmails(
        List<Contact> newContacts,
        Map<Id, Contact> oldContactsById
    ) {
        List<Contact> contactsToCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> normalizedEmails = new Set<String>();
        Set<Id> contactIdsToCheck = new Set<Id>();

        for (Contact newContact : newContacts) {
            if (newContact.AccountId == null || String.isBlank(newContact.Email)) {
                continue;
            }

            if (oldContactsById != null) {
                Contact oldContact = oldContactsById.get(newContact.Id);
                if (
                    oldContact != null &&
                    newContact.AccountId == oldContact.AccountId &&
                    newContact.Email == oldContact.Email
                ) {
                    continue;
                }
            }

            contactsToCheck.add(newContact);
            accountIds.add(newContact.AccountId);
            normalizedEmails.add(normalizeEmail(newContact.Email));
            if (newContact.Id != null) {
                contactIdsToCheck.add(newContact.Id);
            }
        }

        if (contactsToCheck.isEmpty()) {
            return;
        }

        // Without sharing is intentional so the uniqueness rule is enforced
        // against every Contact, while only a generic validation error is exposed.
        Set<String> existingKeys = new Set<String>();
        for (Contact existingContact : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE
                AccountId IN :accountIds
                AND Email IN :normalizedEmails
                AND Id NOT IN :contactIdsToCheck
        ]) {
            if (
                existingContact.AccountId != null &&
                String.isNotBlank(existingContact.Email)
            ) {
                existingKeys.add(
                    keyFor(existingContact.AccountId, existingContact.Email)
                );
            }
        }

        Set<String> seenKeys = new Set<String>();
        for (Contact contactToCheck : contactsToCheck) {
            String key = keyFor(contactToCheck.AccountId, contactToCheck.Email);
            if (existingKeys.contains(key) || seenKeys.contains(key)) {
                contactToCheck.addError(DUPLICATE_EMAIL_ERROR);
            } else {
                seenKeys.add(key);
            }
        }
    }

    private static String keyFor(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + normalizeEmail(email);
    }

    private static String normalizeEmail(String email) {
        return email == null ? null : email.trim().toLowerCase();
    }
}
