/**
 * Maintains Account.FB_Open_Case_Count__c as the count of open
 * (IsClosed = false) Cases for the Account.
 *
 * Recalculates from the database on every relevant Case change so that
 * inserts of already-closed cases, closes, reopens, reparenting, deletes
 * and undeletes are all handled, and an Account left with no open Cases
 * is set to 0 rather than null.
 *
 * Bulk-safe: at most two SOQL queries (one aggregate, one Account query)
 * and at most one DML statement per execution. Runs without sharing so
 * the roll-up counts all open Cases, not only those visible to the
 * running user.
 */
public without sharing class TA_Case_RollupOpenCount
    implements
        TriggerAction.AfterInsert,
        TriggerAction.AfterUpdate,
        TriggerAction.AfterDelete,
        TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        recalculate(collectAccountIds(triggerNew, null));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        // Collect from both old and new so closures/reopens (IsClosed change)
        // and moves between Accounts (AccountId change) recalculate both
        // the source and target Accounts, regardless of which field changed.
        recalculate(collectAccountIds(triggerNew, triggerOld));
    }

    public void afterDelete(List<SObject> triggerOld) {
        recalculate(collectAccountIds(triggerOld, null));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        recalculate(collectAccountIds(triggerNew, null));
    }

    private Set<Id> collectAccountIds(List<SObject> records, List<SObject> otherRecords) {
        Set<Id> accountIds = new Set<Id>();
        addAccountIds(accountIds, records);
        addAccountIds(accountIds, otherRecords);
        return accountIds;
    }

    private void addAccountIds(Set<Id> accountIds, List<SObject> records) {
        if (records == null) {
            return;
        }
        for (SObject record : records) {
            Case caseRecord = (Case) record;
            if (caseRecord.AccountId != null) {
                accountIds.add(caseRecord.AccountId);
            }
        }
    }

    private void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Default every affected Account to 0 so Accounts whose last open
        // Case was closed, moved, or deleted are reset to 0, not blank.
        Map<Id, Integer> openCountByAccountId = new Map<Id, Integer>();
        for (Id accountId : accountIds) {
            openCountByAccountId.put(accountId, 0);
        }

        for (AggregateResult result : [
            SELECT AccountId, COUNT(Id) openCount
            FROM Case
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('AccountId');
            if (accountId != null) {
                openCountByAccountId.put(accountId, (Integer) result.get('openCount'));
            }
        }

        // Only update Accounts whose stored value is stale; also ensures
        // we never attempt DML on an Account that no longer exists.
        List<Account> accountsToUpdate = new List<Account>();
        for (Account accountRecord : [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Integer openCount = openCountByAccountId.get(accountRecord.Id);
            if (openCount == null) {
                openCount = 0;
            }
            if (
                accountRecord.FB_Open_Case_Count__c == null ||
                accountRecord.FB_Open_Case_Count__c.intValue() != openCount
            ) {
                accountsToUpdate.add(
                    new Account(
                        Id = accountRecord.Id,
                        FB_Open_Case_Count__c = openCount
                    )
                );
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
