public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    private static final Set<Id> processedIds = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>(triggerOld);
        List<Task> tasksToInsert = new List<Task>();

        for (Opportunity opp : triggerNew) {
            // Only consider the first after-update sighting of a record in
            // this transaction. TA_Opportunity_RoundAmount (Order 20) runs
            // after this action and its recursive update re-runs this
            // action; that second sighting must not create another Task.
            // Marking records as seen even when Amount is unchanged also
            // prevents a Task when only the recursive rounding changes it.
            if (processedIds.contains(opp.Id)) {
                continue;
            }
            processedIds.add(opp.Id);

            Opportunity oldOpp = oldById.get(opp.Id);
            if (oldOpp != null && opp.Amount != oldOpp.Amount) {
                tasksToInsert.add(
                    new Task(
                        Subject = 'Amount changed',
                        WhatId = opp.Id,
                        Status = 'Completed'
                    )
                );
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
